using System;using System.Data;using System.IO;using System.Linq;
namespace Videira {static class MarketTests {
static void Check(bool c,string m){if(!c)throw new Exception("Mercado: "+m);}
public static void Run(){string root=Path.Combine(Environment.CurrentDirectory,"work","Market-"+Guid.NewGuid());var db=new Store(root);db.Data.Tables["Produtos"].Rows.Add(1,"001","ORIGEM CARMENERE","Existente",44.90m,65m,7m,"Sim");Check(db.ImportPortfolio()==136,"importar 136 novos, vincular Origem existente");Check(db.Data.Tables["Mercado"].Rows.Count==137,"137 rótulos");Check(db.ImportPortfolio()==0&&db.Data.Tables["Produtos"].Rows.Count==137,"importação idempotente");var p=db.Data.Tables["Produtos"].Rows.Find(1);Check((decimal)p["Estoque"]==7m&&(decimal)p["Preço"]==65m&&p["Código"].ToString()=="001"&&p["Fornecedor"].ToString()=="Existente","preservar preço, estoque, fornecedor e código existente");var v=db.MarketView();var origin=v.AsEnumerable().Single(r=>(int)r["Produto"]==1);Check((decimal)origin["Lucro bruto R$"]==20.10m&&(decimal)origin["Markup %"]==44.77m,"65 - 44,90 e markup");p["Custo"]=50m;origin=db.MarketView().AsEnumerable().Single(r=>(int)r["Produto"]==1);Check((decimal)origin["Lucro bruto R$"]==15m&&(decimal)origin["Markup %"]==30m,"custo integrado");var m=db.Data.Tables["Mercado"].Rows[0];m["Moeda"]="EUR";origin=db.MarketView().AsEnumerable().Single(r=>(int)r["Produto"]==1);Check(origin.IsNull("Bodega / mercado R$")&&origin.IsNull("Lucro bruto R$")&&origin.IsNull("Markup %"),"não comparar moeda estrangeira com BRL");m["Moeda"]="BRL";m["Preço referência"]=40m;origin=db.MarketView().AsEnumerable().Single(r=>(int)r["Produto"]==1);Check((decimal)origin["Lucro bruto R$"]==-10m,"referência abaixo do custo");p["Custo"]=0m;Check(db.MarketView().AsEnumerable().Single(r=>(int)r["Produto"]==1).IsNull("Markup %"),"custo zero não divide");db.Save();db=new Store(root);Check(db.Data.Tables["Mercado"].Rows.Count==137&&db.ImportPortfolio()==0,"persistência sem duplicar");File.AppendAllText(Path.Combine(Environment.CurrentDirectory,"work","test-result.txt"),"\r\nPASS 2.3 Mercado: 137 rótulos, importação única, preservação existente, markup, lucro, custo vinculado, moeda estrangeira, custo zero, resultado negativo e persistência.");}
}}
